"""Map runtime exceptions onto the stable RUN_ERROR code vocabulary.

The vocabulary itself (``RunErrorCode``) lives with the event builders in
``ag_ui_events``; this module owns the exception-to-code mapping so callers that
only need to classify a failure need not import the copilot runtime.
"""

from __future__ import annotations

from typing import Any

import httpx
import structlog

from rasa.builder.copilot.pydantic_ai import ag_ui_events

try:
    from pydantic_ai.exceptions import (
        ModelAPIError,
        ModelHTTPError,
        UnexpectedModelBehavior,
        UsageLimitExceeded,
    )
except ImportError as exc:
    raise ImportError(
        "pydantic-ai-slim is required for Copilot v2. "
        "Install with: pip install rasa-pro[copilot-v2]"
    ) from exc

structlogger = structlog.get_logger()


def classify_run_error(exc: BaseException) -> ag_ui_events.RunErrorCode:
    """Map an exception onto the stable RUN_ERROR code vocabulary.

    Exception classes shift under dependency upgrades, so the mapping is
    deliberately coarse: downstream metrics group on the code vocabulary, and
    the real class goes to the logs. Exceptions raised inside the agent graph's
    task group can surface wrapped in a ``BaseExceptionGroup``, so unwrap
    recursively and classify on the first member that is not the fallback.
    """
    if isinstance(exc, BaseExceptionGroup):
        for member in exc.exceptions:
            code = classify_run_error(member)
            if code is not ag_ui_events.RunErrorCode.RUNTIME_EXCEPTION:
                return code
        return ag_ui_events.RunErrorCode.RUNTIME_EXCEPTION
    if isinstance(exc, TimeoutError):
        return ag_ui_events.RunErrorCode.TIMEOUT
    if isinstance(exc, UsageLimitExceeded):
        return ag_ui_events.RunErrorCode.MAX_TURNS
    if isinstance(
        exc,
        (
            ModelHTTPError,
            ModelAPIError,
            UnexpectedModelBehavior,
            httpx.TimeoutException,
        ),
    ):
        return ag_ui_events.RunErrorCode.MODEL_ERROR
    return ag_ui_events.RunErrorCode.RUNTIME_EXCEPTION


def run_error_event(exc: Exception, thread_id: str) -> dict[str, Any]:
    """Log a failed run and build its RUN_ERROR event."""
    code = classify_run_error(exc)
    structlogger.warning(
        "copilot_v2.run.failed",
        error_type=type(exc).__name__,
        code=code.value,
        thread_id=thread_id,
    )
    return ag_ui_events.run_error(str(exc), code)
